  ('05379e3c-849b-5686-b55b-e5753f2284fb', 'Cuidarlo si tiene una crisis', 'Que esté seguro durante una crisis y el equipo se entere enseguida.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('0dd8a58f-78f5-5c19-98e2-6528bd027e15', 'Darle descanso a la familia', 'Que la familia pueda descansar mientras vos cuidás.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('090a0580-754d-57d1-8688-2418bd34b286', 'Descansar bien', 'Que duerma de noche y descanse en un lugar tranquilo.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('bb29ead0-8afd-58fb-9745-4b10fbb0f866', 'Dormir bien', 'Que duerma de noche en sus horarios.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('ac2b8dda-276a-5cfa-b530-44b8b6d16f02', 'Dormir de noche', 'Que duerma de noche en sus horarios.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('6a6a8a94-46ac-5242-8db1-33dde859bfcd', 'Estar acompañado', 'Que converse y no se aísle.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('a223f2f3-dd1a-53a5-aafa-11c37a978ada', 'Estar limpio cada día', 'Que esté limpio y arreglado todos los días.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('288de472-77f2-5ebb-95a2-ae4b1ea71d77', 'Estar limpio cada día', 'Que se bañe y se cambie la ropa todos los días.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('ee4fada5-4fbf-5045-bbc9-a5863ff09aa2', 'Estar limpio y comer bien', 'Que se bañe, se cambie y haga sus comidas.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('5100d432-ce7f-51e3-b6f8-f81cd88e41e9', 'Estar seguro en casa', 'Que no tenga accidentes en la casa.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('b3a6be0a-afde-585f-aee2-392a5b10c8f7', 'Estar tranquilo', 'Que esté calmado y, si se pone nervioso, se calme con ayuda.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('2521d582-73ef-5eb7-9d66-1ab57b940f26', 'Estar tranquilo en casa', 'Que no haya peleas. No hace falta discutirle lo que piensa.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('65ceb3f6-380a-5510-b60c-8fbd27e8669d', 'Hacer algo en el día', 'Que haga al menos una actividad y no pase el día sin hacer nada.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('c76a2d02-8e41-5465-a70d-f2cb35ff374b', 'Hacer algo en el día', 'Que haga alguna actividad que le guste.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('f1ae91aa-d68c-59de-a01b-fd4905ae8f57', 'Hacer los controles indicados', 'Que se hagan los controles que pidió el médico, como presión, azúcar o temperatura.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('746cddee-c40b-5136-9883-6164d24315e2', 'Hacer los cuidados especiales', 'Que se hagan los cuidados que indicó el equipo médico.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('ad80fa38-0cd5-5bb1-89dd-d004e6526be6', 'Hacer los ejercicios indicados', 'Que haga los ejercicios que indicó el equipo.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('587743ba-d1d1-5617-86fa-eedf4d27195b', 'Ir al baño', 'Que vaya al baño en los horarios acordados.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('993046b4-9344-50ac-aeff-9b363ede3d25', 'Jugar cada día', 'Que juegue y haga actividades para su edad.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('c120b897-eb1f-56ef-8f89-a145a4a95e82', 'Moverse sin caerse', 'Que se mueva por la casa sin caerse.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('a9d8b772-86d1-54cf-bef8-cdfd62677628', 'No quedarse aislado', 'Que converse y salga un poco cada día.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('4d47f4df-ae11-5837-ae28-3e6a61c11ff7', 'Recibir estímulos cada día', 'Que escuche voces, música y sienta contacto cada día.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('7d7340f3-a4c6-502d-94c6-d7c2f6beddce', 'Seguir la rutina del día', 'Que haga las cosas del día en el orden de siempre.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('f6338f23-251c-5aeb-ad14-0968d83f6c6c', 'Tomar los remedios a horario', 'Que tome los remedios a la hora indicada.', 'CAREGIVER', 'seed:587', 'seed:587'),
  ('4150c42b-2dd2-5cf6-9d37-490d2ae7bd6c', 'Usar el aparato para dormir', 'Que use cada noche el aparato que indicó el médico.', 'CAREGIVER', 'seed:587', 'seed:587')
