INSERT INTO therapeutic_activities (id, label, description, objective_id, suggested_frequency, created_by, updated_by) VALUES
  ('63ff4ff0-74c6-53e3-862f-a846483b44fb', 'Cumplir su plan del día', 'Realiza las actividades del día según lo acordado.', '0126e26a-3ea0-5549-be2a-60a85174906d', 'Cada guardia', 'seed:587', 'seed:587'),
  ('5937edea-6d1d-5d22-b1a9-58bc38489a52', 'Registrar días sin consumo', 'Cuenta al AT si consumió desde la guardia anterior.', '022da5a9-4ddc-5258-848a-34560948f87d', 'Cada guardia', 'seed:587', 'seed:587'),
  ('e110c8fb-4a65-5647-a522-1f400c5c93b5', 'Usar una alternativa ante las ganas', 'Pone en práctica la alternativa acordada cuando aparecen las ganas de consumir.', '022da5a9-4ddc-5258-848a-34560948f87d', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('22641214-5603-5218-894c-6111df6a4d58', 'Hacer los controles indicados', 'Se hace o se le hace el control indicado (presión, temperatura u otro) y se anota.', '02bea07b-26f9-53c9-9715-39a29648a45b', 'Según indicación', 'seed:587', 'seed:587'),
  ('57432209-fe86-5552-8479-4abaf904ae53', 'Llevar su registro de salud', 'Anota con el AT turnos, estudios e indicaciones.', '02bea07b-26f9-53c9-9715-39a29648a45b', 'Semanal', 'seed:587', 'seed:587'),
  ('787f8605-ebf7-5471-bccf-d138b91792a7', 'Hacer ejercicios suaves', 'Realiza los ejercicios suaves indicados.', '03c7bbe2-efdd-512b-9268-0a50d7271f22', 'Diaria', 'seed:587', 'seed:587'),
  ('28a43ce0-3491-56a2-ac77-906fc3bc9161', 'Salir a caminar', 'Camina el tiempo acordado, a su ritmo.', '03c7bbe2-efdd-512b-9268-0a50d7271f22', 'Diaria', 'seed:587', 'seed:587'),
  ('018209d1-0707-50c1-ac6f-ce1d6c660a59', 'Cuidarlo durante una crisis', 'Si tiene una convulsión, ponelo de costado, no le pongas nada en la boca, mirá la hora y avisá enseguida.', '05379e3c-849b-5686-b55b-e5753f2284fb', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('94f1572d-8249-5e7d-936d-8b7e32a8ccf1', 'Contar cambios en lo que percibe', 'Comenta al AT si notó experiencias nuevas o más intensas. Un Sí se avisa a coordinación.', '08fa38fd-a931-55b3-8420-519a7f7a4627', 'Cada guardia', 'seed:587', 'seed:587'),
  ('b78addfe-94b7-527d-88c9-82601907e2de', 'Comer las comidas del día', 'Fijate que coma cada comida. Marcá Sí o No.', '090a0580-754d-57d1-8688-2418bd34b286', 'Cada comida', 'seed:587', 'seed:587'),
  ('8e05017b-80e4-5860-999a-c2a4f0c41b59', 'Dormir de noche', 'Preguntale o fijate si durmió de noche. Marcá Sí o No.', '090a0580-754d-57d1-8688-2418bd34b286', 'Diaria', 'seed:587', 'seed:587'),
  ('faed6acf-67dc-526e-b032-2ed5d7c5e4df', 'Contar cambios en lo que percibe', 'Comenta al AT si notó experiencias nuevas o más intensas. Un Sí se avisa a coordinación.', '0a9d5bb1-9e79-5e21-90c2-fa29c005859f', 'Cada guardia', 'seed:587', 'seed:587'),
  ('d248500b-3071-5f98-8fcf-584967cd76f3', 'Cubrir el horario de relevo', 'Quedate con la persona en el horario acordado para que la familia descanse. Marcá Sí o No.', '0dd8a58f-78f5-5c19-98e2-6528bd027e15', 'Según cronograma', 'seed:587', 'seed:587'),
  ('00280852-5e19-5712-b3c8-e03392ae499c', 'Hacer una compra simple', 'Elige, paga y recibe el vuelto en una compra simple.', '0f80c96b-2d64-54e5-b689-45d09f000e80', 'Semanal', 'seed:587', 'seed:587'),
  ('3f28f3f0-f5b9-55b7-a802-ce6f0acecd72', 'Usar el transporte con apoyo', 'Hace un recorrido en transporte con el apoyo necesario.', '0f80c96b-2d64-54e5-b689-45d09f000e80', 'Semanal', 'seed:587', 'seed:587'),
  ('0e0cc9a6-6a3d-5906-93fc-19a70f7d27ff', 'Terminar una tarea con pasos', 'Termina una tarea dividida en pasos cortos, con pausas acordadas.', '10933d84-043d-593f-9470-651e12cf5837', 'Cada guardia', 'seed:587', 'seed:587'),
  ('59888033-e2e7-52d4-8f1d-c3ba73373a72', 'Usar su agenda o recordatorios', 'Usa la agenda, alarmas o notas para organizar sus tareas.', '10933d84-043d-593f-9470-651e12cf5837', 'Diaria', 'seed:587', 'seed:587'),
  ('84bc145f-82fe-50ef-99d5-24df6d58c091', 'Elegir y hacer una actividad propia', 'Elige una actividad que le interese y la realiza, aunque sea breve.', '113e4dd9-faa2-530a-b673-124a7a30ed9b', 'Cada guardia', 'seed:587', 'seed:587'),
  ('9ff4fd20-7a18-55ba-b3c5-8a5584493675', 'Ordenar su espacio', 'Ordena su habitación o su lugar de la casa.', '142656ac-cad6-5751-82c0-72bf78b3f423', 'Diaria', 'seed:587', 'seed:587'),
  ('7aa52cb0-bc1f-53ea-88ef-8e477e412243', 'Organizar su día', 'Arma con el AT la agenda del día y cumple al menos una tarea elegida.', '142656ac-cad6-5751-82c0-72bf78b3f423', 'Cada guardia', 'seed:587', 'seed:587'),
  ('2e093478-be1e-5259-a5d3-79902af99eee', 'Avisar si tiene dolor', 'Dice o muestra si le duele algo. El AT registra el dolor que observa.', '1755b642-efea-5b20-96e9-c137e95aec1d', 'Cada guardia', 'seed:587', 'seed:587'),
  ('eb7fd066-476e-5a11-bd08-2baeeb5b6cc7', 'Hacer pausas de descanso', 'Realiza las pausas de descanso y los cambios de postura indicados.', '1755b642-efea-5b20-96e9-c137e95aec1d', 'Cada guardia', 'seed:587', 'seed:587'),
  ('5e4c55b5-6313-53c1-8fce-30317dd938ac', 'Comunicar conductas alimentarias de riesgo', 'Revisa con el AT si hubo restricción, atracón, vómito o ejercicio excesivo. Cualquier conducta se avisa a coordinación.', '1767e53c-3e5c-5ad8-b64b-21e2210970ec', 'Cada guardia', 'seed:587', 'seed:587'),
  ('6cdc3f22-4d1e-530b-9382-ba302ef9cec4', 'Quedarse acompañado después de comer', 'Permanece acompañado después de comer el tiempo acordado con el equipo.', '1767e53c-3e5c-5ad8-b64b-21e2210970ec', 'Cada comida', 'seed:587', 'seed:587'),
  ('5a725eaa-0e5f-51ad-88d4-9e49fd7cfe97', 'Realizar las comidas pautadas', 'Realiza las comidas indicadas en el plan del equipo durante la guardia.', '1767e53c-3e5c-5ad8-b64b-21e2210970ec', 'Cada comida', 'seed:587', 'seed:587'),
  ('b9581ba3-2180-537c-9ea6-324f484fe97b', 'Practicar una situación social', 'Ensaya con el AT una situación que le cuesta, como pedir algo en un comercio.', '1f4c388e-c7a6-58cb-8641-dd074c90aacd', 'Semanal', 'seed:587', 'seed:587'),
  ('352f2115-c37c-53e8-bac6-51d5db12b41c', 'Comer y tomar líquidos', 'El AT registra si comió y tomó líquidos durante la guardia. Un No se avisa a coordinación.', '1f51376a-d75f-5270-ac1d-1a39a2ef64e9', 'Cada guardia', 'seed:587', 'seed:587'),
  ('d6b79593-36c4-53e8-9e5c-07cce168cb5b', 'Registrar cambios en el movimiento', 'El AT observa si está muy quieto, rígido o muy inquieto.', '1f51376a-d75f-5270-ac1d-1a39a2ef64e9', 'Cada guardia', 'seed:587', 'seed:587'),
  ('d2cea372-b10d-59d9-9c18-ba65c92a1b7a', 'Comer las comidas del día', 'Fijate que coma cada comida. Marcá Sí o No.', '2521d582-73ef-5eb7-9d66-1ab57b940f26', 'Cada comida', 'seed:587', 'seed:587'),
  ('9b02c416-1076-5c11-b9a0-36c0f61d3c19', 'Contar las peleas', 'Si hubo una pelea o una discusión fuerte, marcá cuántas veces pasó.', '2521d582-73ef-5eb7-9d66-1ab57b940f26', 'Diaria', 'seed:587', 'seed:587'),
  ('734f0b77-8789-5266-b82e-8aaf7fd24207', 'Conversar sin discutir', 'Escuchalo con calma. No discutas lo que piensa. Marcá cómo estuvo.', '2521d582-73ef-5eb7-9d66-1ab57b940f26', 'Diaria', 'seed:587', 'seed:587'),
  ('ed3e0b06-626e-58a3-8bc9-05255c1a98e9', 'Ordenar el uso del dinero', 'Revisa con el AT o un referente sus gastos, según lo acordado.', '27418809-58a0-5239-b4d3-4f5eadb75042', 'Semanal', 'seed:587', 'seed:587'),
  ('092ec925-bc58-5c69-8ac6-d16d573f3f89', 'Registrar días sin juego', 'Cuenta al AT si jugó desde la guardia anterior.', '27418809-58a0-5239-b4d3-4f5eadb75042', 'Cada guardia', 'seed:587', 'seed:587'),
  ('355177c3-c9f4-5b6d-b0f8-982355eac246', 'Usar una alternativa ante el impulso de jugar', 'Pone en práctica la alternativa acordada cuando aparecen las ganas de jugar.', '27418809-58a0-5239-b4d3-4f5eadb75042', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('2d5734e1-0912-5022-a2e7-3252dd3c5cd9', 'Bañarse', 'Animalo a bañarse. Dejá que lo haga solo. Marcá cómo lo hizo.', '288de472-77f2-5ebb-95a2-ae4b1ea71d77', 'Diaria', 'seed:587', 'seed:587'),
  ('5e358178-2a8f-55c5-8e87-1b7677df0bbe', 'Ponerse ropa limpia', 'Fijate que se cambie la ropa. Marcá cómo lo hizo.', '288de472-77f2-5ebb-95a2-ae4b1ea71d77', 'Diaria', 'seed:587', 'seed:587'),
  ('b257daff-8a8c-55f5-96be-1ba55a2c4bda', 'Avisar si está distinto', 'Si está muy desconfiado o dice cosas raras, avisá. Marcá si pasó algo.', '2918e875-0831-5708-9a01-f0278e207baf', 'Cada turno', 'seed:587', 'seed:587'),
  ('4775d097-cb91-52a5-a449-47770bd10728', 'Avisar si está distinto', 'Si está muy triste, muy acelerado, no duerme o habla solo, avisá enseguida. Marcá si pasó algo.', '29e5faf5-ae62-588a-a55e-0a2bdcfe5fd8', 'Cada turno', 'seed:587', 'seed:587'),
  ('16068061-9c07-598f-9853-e58331bc0b18', 'Ver cómo está de ánimo', 'Fijate cómo estuvo en el día. Marcá cómo estuvo.', '29e5faf5-ae62-588a-a55e-0a2bdcfe5fd8', 'Diaria', 'seed:587', 'seed:587'),
  ('f25a4cae-2d48-5add-a0a1-728923a0e2cb', 'Comer de manera autónoma', 'Come por sus propios medios, con adaptaciones si las necesita.', '2b404a9c-9ed9-5bdf-9f35-9d42abde12c7', 'Cada comida', 'seed:587', 'seed:587'),
  ('0e675c35-0441-55ea-bfd2-02e39c9fe221', 'Realizar su higiene personal', 'Se baña y se arregla con el apoyo mínimo necesario.', '2b404a9c-9ed9-5bdf-9f35-9d42abde12c7', 'Diaria', 'seed:587', 'seed:587'),
  ('ec7b63c6-2b48-51f5-9e24-f6dd33391860', 'Vestirse por sí mismo', 'Se viste eligiendo su ropa, con ayuda solo si la necesita.', '2b404a9c-9ed9-5bdf-9f35-9d42abde12c7', 'Diaria', 'seed:587', 'seed:587'),
  ('ba441406-23fb-58a3-b76f-d1c2ccdb2b6b', 'Avisar si está distinto', 'Si habla solo, está muy desconfiado o no duerme, avisá enseguida. Marcá si pasó algo.', '2cc59727-0d34-558c-ad49-19a12887049b', 'Cada turno', 'seed:587', 'seed:587'),
  ('71668740-b546-5ebc-a9b2-2af2f67fdc0f', 'Conversar sobre sus metas', 'Comenta con el AT qué avanzó en sus metas de la semana.', '30d6cd25-1bd6-5013-b610-a851637fc76b', 'Semanal', 'seed:587', 'seed:587'),
  ('193c8ed2-e827-52f3-a26e-44e4bc894556', 'Hacer una actividad significativa', 'Elige y realiza una actividad vinculada a sus metas personales.', '30d6cd25-1bd6-5013-b610-a851637fc76b', 'Cada guardia', 'seed:587', 'seed:587'),
  ('33a7689d-fcad-5aa7-8d33-d4208051b891', 'Comer sentado y despacio', 'Sentalo derecho y dale tiempo para comer. Si se atraganta, avisá. Marcá si se atragantó.', '361f27c8-4490-5f3e-9f01-e7dbf3e683ea', 'Cada comida', 'seed:587', 'seed:587'),
  ('7ba46481-4a5f-52b4-8802-f9523eb84946', 'Asistir a la escuela o al trabajo', 'Concurre a su actividad escolar, educativa o laboral.', '3c104aee-b911-54c2-81ac-abf2eb32ea41', 'Según cronograma', 'seed:587', 'seed:587'),
  ('bcaaa0aa-29d2-521a-9d1e-d9e6e49cec76', 'Completar la tarea del día', 'Completa la tarea escolar o laboral del día con los apoyos acordados.', '3c104aee-b911-54c2-81ac-abf2eb32ea41', 'Diaria', 'seed:587', 'seed:587'),
  ('cea0728d-103d-573c-8165-e996d4644be9', 'Expresar cómo se siente', 'Cuenta o muestra cómo se siente. El AT registra el ánimo que observa.', '3c8ead50-ccea-5483-8aea-e740a969e5d7', 'Cada guardia', 'seed:587', 'seed:587'),
  ('58e943d0-ed75-512d-95c5-eee5f3d4ad86', 'Registrar señales de aceleración', 'El AT observa si habla muy rápido, duerme poco sin cansancio o gasta de más. Cualquier señal se avisa a coordinación.', '3c8ead50-ccea-5483-8aea-e740a969e5d7', 'Cada guardia', 'seed:587', 'seed:587'),
  ('db6bd475-71f8-57e9-ac3b-320378e92434', 'Comer sentado en la mesa', 'Come sentado en la mesa durante toda la comida.', '3d0c9a4b-8822-5e7c-a8f1-b25666f40c0e', 'Cada comida', 'seed:587', 'seed:587'),
  ('ebfd4481-72f1-57a4-937a-83cf57bc939a', 'Lavarse las manos y los dientes', 'Sigue la secuencia de pictogramas para lavarse.', '3d0c9a4b-8822-5e7c-a8f1-b25666f40c0e', 'Diaria', 'seed:587', 'seed:587'),
  ('708c22bc-b439-5703-8620-484092bf07f4', 'Vestirse con secuencia visual', 'Se viste siguiendo los pasos de su secuencia visual.', '3d0c9a4b-8822-5e7c-a8f1-b25666f40c0e', 'Diaria', 'seed:587', 'seed:587'),
  ('1a0f659c-04c2-5c1c-88e1-7bfa9c9115ad', 'Comer las comidas del día', 'Fijate que coma cada comida. Marcá Sí o No.', '4149b086-5ba6-5d8a-a34d-f2e43a7aa8a7', 'Cada comida', 'seed:587', 'seed:587'),
  ('65d23857-53f7-530a-b9d2-012302bb7a60', 'Tomar agua', 'Ofrecele agua varias veces. Marcá si tomó.', '4149b086-5ba6-5d8a-a34d-f2e43a7aa8a7', 'Diaria', 'seed:587', 'seed:587'),
  ('2906b64d-3ca9-5989-95a3-e28c14cd121c', 'Ponerse el aparato', 'Recordale que se ponga el aparato para dormir. Marcá Sí o No.', '4150c42b-2dd2-5cf6-9d37-490d2ae7bd6c', 'Diaria', 'seed:587', 'seed:587'),
  ('7481a48d-4f86-514e-9bc1-007e4c8a3a9a', 'Registrar cada crisis', 'Si hay una crisis, el AT registra hora, duración y qué estaba haciendo, y avisa a coordinación.', '45d5a096-b34b-59ea-89c6-49dc0b7d36e5', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('d306240a-435a-5003-8497-1b36ed5dd901', 'Respetar sus horarios de descanso', 'Duerme y descansa en los horarios acordados.', '45d5a096-b34b-59ea-89c6-49dc0b7d36e5', 'Diaria', 'seed:587', 'seed:587'),
