  ('dbf28716-a145-5af9-a249-c346bcff19ee', 'Dormir de noche', 'Preguntale o fijate si durmió de noche. Marcá Sí o No.', 'bb29ead0-8afd-58fb-9745-4b10fbb0f866', 'Diaria', 'seed:587', 'seed:587'),
  ('80e555ea-f15e-5b7e-b814-8bbf4bb7d64b', 'Caminar acompañado', 'Caminá a su lado y que use su bastón o andador si lo tiene. Marcá cuántas veces se cayó.', 'c120b897-eb1f-56ef-8f89-a145a4a95e82', 'Diaria', 'seed:587', 'seed:587'),
  ('2a0c73ff-fb81-5a99-b6a1-4c60da8989f0', 'Registrar cambios en el movimiento', 'El AT observa si está muy inquieto, muy lento o se queda quieto mucho tiempo.', 'c3135f10-f130-5096-a2e1-6a6b6dfe9aaf', 'Cada guardia', 'seed:587', 'seed:587'),
  ('87e4ca1f-862e-5daa-a3ff-707d092c8194', 'Iniciar una conversación', 'Inicia una conversación con otra persona.', 'c45a7ba4-6475-50d3-bde0-8489e8759b70', 'Cada guardia', 'seed:587', 'seed:587'),
  ('7e4830cb-c2e6-554d-a0cd-18638d0717f6', 'Participar en una actividad grupal', 'Participa de una actividad con otras personas.', 'c45a7ba4-6475-50d3-bde0-8489e8759b70', 'Semanal', 'seed:587', 'seed:587'),
  ('d2a09e1b-d7c9-5230-aced-3b3828be9a1b', 'Preparar un dormitorio seguro', 'Revisa con el AT que no haya objetos peligrosos y que puertas y ventanas estén aseguradas.', 'c6e6984b-9482-5485-ae59-bc32ae39e15b', 'Diaria', 'seed:587', 'seed:587'),
  ('b468a120-0f33-5756-9834-94cd08e2a879', 'Registrar episodios nocturnos', 'El AT registra los episodios nocturnos que le refieren o que observa.', 'c6e6984b-9482-5485-ae59-bc32ae39e15b', 'Cada guardia', 'seed:587', 'seed:587'),
  ('4aae83d1-abdf-5b23-a374-3eb5b0a77dea', 'Hacer las siestas programadas', 'Duerme las siestas en los horarios indicados por el equipo.', 'c72cf4a9-2abb-54c6-8a31-4b44abd9399d', 'Diaria', 'seed:587', 'seed:587'),
  ('7d01edad-9591-5ffe-b142-64a28969a7a6', 'Registrar episodios de somnolencia', 'El AT registra cuántas veces se quedó dormido fuera de lo programado.', 'c72cf4a9-2abb-54c6-8a31-4b44abd9399d', 'Cada guardia', 'seed:587', 'seed:587'),
  ('9ca06072-7458-5c97-a1ab-f97a6340df04', 'Hacer una actividad', 'Invitalo a hacer algo que le guste. Marcá cómo lo hizo.', 'c76a2d02-8e41-5465-a70d-f2cb35ff374b', 'Diaria', 'seed:587', 'seed:587'),
  ('67b9bbbc-b68e-530d-8eb3-c487d6c69662', 'Repasar su plan de seguridad', 'Repasa con el AT los pasos y los contactos de su plan de seguridad.', 'ca7d32ab-4034-559b-8275-8c29b97bb595', 'Semanal', 'seed:587', 'seed:587'),
  ('29bc72b1-e371-53e7-9f2e-85970178f039', 'Revisar sus señales de alerta', 'El AT observa si aparece alguna señal de la lista acordada en el PT. Cualquier señal se avisa a coordinación.', 'ca7d32ab-4034-559b-8275-8c29b97bb595', 'Cada guardia', 'seed:587', 'seed:587'),
  ('a342ccbd-e7c7-57ae-84c7-fce6f5dcfd41', 'Hacer una actividad que lo distraiga', 'Realiza una actividad agradable que lo aleje un rato de sus preocupaciones.', 'cbf63b06-3525-5373-a8f2-dcf128c0bf54', 'Cada guardia', 'seed:587', 'seed:587'),
  ('d9d4a058-ff28-538b-a9c3-3b3085493cdc', 'Registrar consultas médicas no programadas', 'El AT registra si pidió o hizo consultas médicas no programadas.', 'cbf63b06-3525-5373-a8f2-dcf128c0bf54', 'Cada guardia', 'seed:587', 'seed:587'),
  ('0a0a118c-ae7f-5800-8294-ea7556ad0d5b', 'Nombrar cómo se siente', 'Señala o dice cómo se siente usando apoyos de emociones.', 'd4f952e9-35e0-5fdb-9a71-aeff66a0df32', 'Cada guardia', 'seed:587', 'seed:587'),
  ('972d2533-01b2-5dea-b25c-8eb6e0ab383c', 'Usar su recurso de calma', 'Va a su rincón o usa su recurso de calma cuando se frustra.', 'd4f952e9-35e0-5fdb-9a71-aeff66a0df32', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('4d909324-b38c-5c97-a0a4-65bd351274ef', 'Avisar si está distinto', 'Si está más confundido, asustado o habla solo, avisá enseguida. Marcá si pasó algo.', 'd611ad32-11f4-5430-872a-d42adef80751', 'Cada turno', 'seed:587', 'seed:587'),
  ('3fa5f6ea-c612-5f1c-bf89-d98a8b8545ca', 'Ver cómo está', 'Fijate cómo estuvo en el día. Marcá cómo estuvo.', 'd611ad32-11f4-5430-872a-d42adef80751', 'Diaria', 'seed:587', 'seed:587'),
  ('09901cc8-7c3b-55d8-933c-31a8a1999f47', 'Expresar cómo se siente', 'Cuenta o muestra cómo se siente. El AT registra el ánimo que observa.', 'd95483ec-c26b-5e55-85a7-74da52ca4c62', 'Cada guardia', 'seed:587', 'seed:587'),
  ('652f41e4-79d0-55f6-8a1a-197756109021', 'Practicar lectura, escritura o cálculo', 'Practica la habilidad escolar indicada con los apoyos acordados.', 'da4503d1-2f1e-5f05-8464-ece6562602d8', 'Diaria', 'seed:587', 'seed:587'),
  ('ec34e675-353c-5a3d-bbe2-61482bd22a27', 'Usar sus apoyos escolares', 'Usa los apoyos acordados: agenda, organizadores, tiempos extra.', 'da4503d1-2f1e-5f05-8464-ece6562602d8', 'Diaria', 'seed:587', 'seed:587'),
  ('8b785c61-df17-56d5-9988-4b9ff711956e', 'Contar cómo durmió', 'Cuenta cómo durmió la noche anterior. El AT registra lo que le refiere y lo que observa.', 'e4115c58-6d4a-55dd-a9ef-eeddfcc4f280', 'Cada guardia', 'seed:587', 'seed:587'),
  ('265d57bc-38a1-5142-8ef6-e63bcd3fd8bf', 'Cumplir su horario de sueño', 'Se acuesta y se levanta en el horario acordado.', 'e4115c58-6d4a-55dd-a9ef-eeddfcc4f280', 'Diaria', 'seed:587', 'seed:587'),
  ('fd7ade0e-00d7-5317-9f37-5f5197504d24', 'Contar cambios en lo que percibe', 'Comenta al AT si notó experiencias nuevas o más intensas. Un Sí se avisa a coordinación.', 'e43d6b6e-5f1f-56f4-a753-02c74ed9e929', 'Cada guardia', 'seed:587', 'seed:587'),
  ('53265097-449a-5462-863e-222b15deb6d6', 'Hacer una tarea con pasos', 'Realiza una tarea con principio y fin, como cocinar algo sencillo o un trámite corto.', 'e4aae4bf-4d77-5d3b-864e-5af859c5a320', 'Cada guardia', 'seed:587', 'seed:587'),
  ('2e3451e8-800d-51ae-b33f-6d845a6ef574', 'Avisar si está distinto', 'Si habla solo, está muy quieto, muy inquieto o muy triste, avisá. Marcá si pasó algo.', 'e9d84ca5-6189-5d36-b733-5bb11b7a1241', 'Cada turno', 'seed:587', 'seed:587'),
  ('a12e0d9e-1c67-5fe0-bff6-76e11bee8cd2', 'Ver cómo está', 'Fijate cómo estuvo en el día. Marcá cómo estuvo.', 'e9d84ca5-6189-5d36-b733-5bb11b7a1241', 'Diaria', 'seed:587', 'seed:587'),
  ('74f62429-e846-5b5b-86e5-006917fff3b0', 'Enfrentar una situación evitada', 'Realiza con el AT un paso acordado frente a una situación que evita.', 'ed3d20c9-572d-53c7-883b-5e3596f65187', 'Semanal', 'seed:587', 'seed:587'),
  ('5a6173cc-96fe-560e-a847-c2e4bd2f423b', 'Usar una técnica de relajación', 'Practica la técnica de relajación acordada cuando aparece la ansiedad.', 'ed3d20c9-572d-53c7-883b-5e3596f65187', 'Cada guardia', 'seed:587', 'seed:587'),
  ('3ecdede7-16ef-5d4b-99cd-a3a47a28e6d7', 'Bañarse', 'Animalo a bañarse. Dejá que lo haga solo. Marcá cómo lo hizo.', 'ee4fada5-4fbf-5045-bbc9-a5863ff09aa2', 'Diaria', 'seed:587', 'seed:587'),
  ('5e700e1d-dac3-51c8-9fc7-71590ff78c36', 'Comer las comidas del día', 'Fijate que coma cada comida. Marcá Sí o No.', 'ee4fada5-4fbf-5045-bbc9-a5863ff09aa2', 'Cada comida', 'seed:587', 'seed:587'),
  ('b5233083-e3b9-5761-8135-7e09f70fb845', 'Hacer los controles', 'Hacé los controles que pidió el médico y anotá el número. Marcá Sí o No.', 'f1ae91aa-d68c-59de-a01b-fd4905ae8f57', 'Según indicación', 'seed:587', 'seed:587'),
  ('3114573b-6eea-514d-9f06-d2556a3b4746', 'Registrar los dolores de cabeza', 'El AT registra cuántos episodios hubo y qué estaba haciendo.', 'f49a0d47-8644-57f9-9dfd-3434e114185b', 'Cada guardia', 'seed:587', 'seed:587'),
  ('74e48e81-f4c6-5c9d-9ed4-c365130b0817', 'Sostener comidas y descanso regulares', 'Come y descansa en horarios regulares, como indicó el equipo.', 'f49a0d47-8644-57f9-9dfd-3434e114185b', 'Diaria', 'seed:587', 'seed:587'),
  ('057253b0-9217-54a8-87ab-1a979099744d', 'Registrar los episodios', 'El AT registra cuántos episodios hubo y cuánto duraron.', 'f546061a-fad9-5333-824a-14a4f99c1d6e', 'Cada guardia', 'seed:587', 'seed:587'),
  ('5e563c76-7914-5055-acac-d44c65524adc', 'Volver al presente con un recurso', 'Ante una desconexión, usa con el AT el recurso acordado para volver al presente.', 'f546061a-fad9-5333-824a-14a4f99c1d6e', 'Cuando ocurra', 'seed:587', 'seed:587'),
  ('0d95c0bd-240e-5177-ae2d-4831c8272dbd', 'Tomar los remedios', 'Recordale que tome los remedios a la hora. Marcá Sí o No.', 'f6338f23-251c-5aeb-ad14-0968d83f6c6c', 'Cada toma', 'seed:587', 'seed:587'),
  ('e56989a7-1146-5f67-9f84-6c5c71b4ddcf', 'Descansar mientras otro cuida', 'Toma un descanso mientras otra persona de la red cuida al bebé.', 'f6519fd8-ab52-5249-8426-406685d496a0', 'Diaria', 'seed:587', 'seed:587'),
  ('436cde28-90f1-5c57-b61b-b925bce47e15', 'Realizar un cuidado del bebé', 'Realiza un cuidado del bebé (alimentar, bañar, calmar) con el apoyo necesario.', 'f6519fd8-ab52-5249-8426-406685d496a0', 'Cada guardia', 'seed:587', 'seed:587'),
  ('dac15ac3-6099-5634-8bf1-5e3ea417ab83', 'Comer las comidas del día', 'Fijate que coma cada comida. Marcá Sí o No.', 'f7dea68f-a356-5f2f-ba2b-569ebe4242d2', 'Cada comida', 'seed:587', 'seed:587'),
  ('3a0cb0e1-d30f-5677-bb7b-7f1eca99fd1f', 'Dormir de noche', 'Preguntale o fijate si durmió de noche. Marcá Sí o No.', 'f7dea68f-a356-5f2f-ba2b-569ebe4242d2', 'Diaria', 'seed:587', 'seed:587'),
  ('c5459415-d4dd-5bc8-b9e8-8dfb869d3e3a', 'Retomar una actividad evitada', 'Retoma con el AT, de a poco, una actividad que dejó de hacer.', 'ff73f991-b7b9-5188-a08f-b5e0f79c552d', 'Semanal', 'seed:587', 'seed:587'),
  ('4d7ff4ea-1e6d-5ee5-8794-25770278803f', 'Usar un recurso de anclaje', 'Ante un recuerdo intenso, usa el recurso acordado: respiración, nombrar lo que ve, salir del lugar.', 'ff73f991-b7b9-5188-a08f-b5e0f79c552d', 'Cuando ocurra', 'seed:587', 'seed:587'),
